import itertools, copy
kernel, reference = load_task()
base = example_spec('flce')
def run(BT,H,V,red,ls=0.0,s=0.0,bias=False,ign=-100,lay=None,allign=False,up=None,wstd=0.25,xstd=1.0,frozen=False):
    sp=copy.deepcopy(base)
    sp['tensors']['input']={'shape':[BT,H],'dtype':'float32','requires_grad':True,'init':{'kind':'randn','std':xstd}}
    sp['tensors']['weight']={'shape':[V,H],'dtype':'float32','requires_grad':not frozen,'init':{'kind':'randn','std':wstd}}
    sp['tensors']['target']={'shape':[BT],'dtype':'int64','init':{'kind':'randint','low':0,'high':V},'edits':[{'index':[0],'value':ign}]}
    if allign: sp['tensors']['target']['init']={'kind':'constant','value':ign}; sp['tensors']['target']['edits']=[]
    if bias: sp['tensors']['bias']={'shape':[V],'dtype':'float32','requires_grad':True}
    if lay:
        for k,v in lay.items(): sp['tensors'][k]['layout']=v
    sp['kwargs']={'reduction':red,'label_smoothing':ls,'lse_square_scale':s,'ignore_index':ign}
    sp['upstream']=up or ({'kind':'randn'} if red=='none' else {'kind':'scalar','value':0.7})
    try:
        r=grad_compare(kernel,reference,build_inputs(sp))
    except Exception as e:
        r={'pass':False,'err':repr(e)[:300]}
    if not r['pass']:
        print((BT,H,V,red,ls,s,bias,ign,lay,allign,up,frozen),[ (i['name'],i['ratio'],i['where'][:2]) for i in r.get('items',[]) if not i['passed']], r.get('error'), r.get('err'))
    else: print('ok',BT,H,V,red,lay,allign)
for red in ['mean','sum','none']:
    run(9,5,13,red,allign=True)
    run(9,5,13,red,ls=0.2,s=0.1,bias=True,lay={'input':'transposed','weight':'transposed'})
    run(9,5,13,red,bias=True,lay={'input':'row_strided:2','weight':'col_strided:2'})
    run(9,5,13,red,lay={'input':'offset:3','weight':'offset:5'},ign=4)
    run(6,4,40000,red,ls=0.1,s=0.1,bias=True)
    run(6,4,40000,red,frozen=True,up={'kind':'scalar','value':1.0} if red!='none' else None)
    run(20,6,30,red,ls=0.5,s=0.3,wstd=3.0,xstd=3.0,bias=True,ign=7)
run(9,5,13,'mean',up={'kind':'scalar','value':0.0})
run(9,5,13,'sum',up={'kind':'scalar','value':1.0},ls=0.3)
"}

